sys_script_include.script:
var WorkspacePlanningUtils = Class.create();
WorkspacePlanningUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	// STRY 2 - O mesmo gerente não pode gerir duas bases diferentes.
	getElegibleManagers: function () {
		var excludedManagers = [];
		var gaBase = new GlideAggregate('x_1590365_worksp_0_office_base');
		gaBase.addAggregate('COUNT');
		gaBase.groupBy('manager');
		gaBase.query();

		while (gaBase.next()) {
			var count = Number(gaBase.getAggregate('COUNT'));

			if (count >= 1) {
				excludedManagers.push(gaBase.getValue('manager'));
			}
		}
		var role = 'x_1590365_worksp_0.base_manager';
		var query = "roles=" + role;

		if (excludedManagers.length > 0) {
			query += "^sys_idNOT IN" + excludedManagers.join(",");
		}

		return query;
	},

	// STRY 4 - Não deve ser possível inserir 2 bases com o mesmo nome
	validateSameBaseName: function () {
		var baseName = this.getParameter('sysparm_base_name');

		// Pesquisa se já tem base com o mesmo nome inserido.
		var gaBaseName = new GlideAggregate('x_1590365_worksp_0_office_base');
		gaBaseName.addQuery('name', baseName.toString().trim().toUpperCase());
		gaBaseName.addAggregate('COUNT');
		gaBaseName.query();

		if (gaBaseName.next()) {
			var count = Number(gaBaseName.getAggregate('COUNT'));

			if (count >= 1) {
				var msgSameName = 'There is already a office base with that same name!';
			}
		}

		if (msgSameName) {
			return JSON.stringify({ message: msgSameName });
		} else {
			return JSON.stringify({ message: '' });
		}
	},

	// STRY 4 - Não deve ser possível inserir 2 bases com a mesma cidade e estado
	validateSameCityAndState: function () {
		var baseCity = this.getParameter('sysparm_base_city') || '';
		var baseState = this.getParameter('sysparm_base_state') || '';

		// Pesquisa se já tem base com a mesma cidade e estado inserido.
		var gaBaseCityAndState = new GlideAggregate('x_1590365_worksp_0_office_base');
		gaBaseCityAndState.addQuery('city', baseCity.toString().trim().toUpperCase());
		gaBaseCityAndState.addQuery('state', baseState.toString().trim().toUpperCase());
		gaBaseCityAndState.addAggregate('COUNT');
		gaBaseCityAndState.query();

		if (gaBaseCityAndState.next()) {
			var count2 = Number(gaBaseCityAndState.getAggregate('COUNT'));

			if (count2 >= 1) {
				var msgSameCityAndState = 'There is already a office base with that same city and state!';
			}
		}

		if (msgSameCityAndState) {
			return JSON.stringify({ message: msgSameCityAndState });
		} else {
			return JSON.stringify({ message: '' });
		}
	},

	refQualOfficeBase: function () {
		// STRY 8 - Limitar a uma vez só o cadastro em base, a não ser que a primeira tenha sido rejeitada.
		var allOfficeBases = [];
		var grBasesRegisters = new GlideRecord('x_1590365_worksp_0_base_register');
		grBasesRegisters.addEncodedQuery(
			'userDYNAMIC90d1921e5f510100a9ad2572f2b477fe^state!=4'
		);
		grBasesRegisters.query();

		if (grBasesRegisters.next()) {
			var grOfficeBases = new GlideRecord('x_1590365_worksp_0_office_base');
			grOfficeBases.query();

			while (grOfficeBases.next()) {
				var officeBasesRegistered = grOfficeBases.getValue('sys_id');
				allOfficeBases.push(officeBasesRegistered);
			}
		}

		// STRY 7 - Permitir o usuário se matricular apenas se tiver vagas disponíveis,.
		var notAvailableofficeBases = [];
		var grMaxCapacity = new GlideRecord('x_1590365_worksp_0_office_base');
		grMaxCapacity.addEncodedQuery('available_capacity<=0');
		grMaxCapacity.query();

		while (grMaxCapacity.next()) {
			var fullOfficeBase = grMaxCapacity.getValue('sys_id');
			notAvailableofficeBases.push(fullOfficeBase);
		}

		var queryParts = [];
		if (allOfficeBases.length > 0) {
			queryParts.push('sys_idNOT IN' + allOfficeBases.join(','));
		}
		if (notAvailableofficeBases.length > 0) {
			queryParts.push('sys_idNOT IN' + notAvailableofficeBases.join(','));
		}

		var query = '';
		query = queryParts.join('^');
		return query;
	},

	type: 'WorkspacePlanningUtils'
});
